const CYAN = '#4FC3F7';
const MUTED = 'rgba(204, 217, 229, 0.62)';
const GRID = 'rgba(148, 163, 184, 0.13)';
const frame = context.panel.data.series.find((candidate) =>
  candidate.fields.some((field) => field.type === 'time') &&
  candidate.fields.some((field) => field.type === 'number')
);
const timeField = frame?.fields.find((field) => field.type === 'time');
const valueField = frame?.fields.find((field) => field.type === 'number');
const asArray = (field) => field?.values?.toArray
  ? field.values.toArray()
  : Array.from(field?.values ?? []);
const times = asArray(timeField);
const values = asArray(valueField);
const points = times
  .map((time, index) => {
    const rawValue = values[index];
    return [Number(time), rawValue == null ? Number.NaN : Number(rawValue)];
  })
  .filter(([time, value]) => Number.isFinite(time) && Number.isFinite(value));
const latestPoint = points.length ? points[points.length - 1] : null;
const latestValue = latestPoint?.[1];
const width = context.panel.chart.getWidth();
const compact = width < 230 && Math.abs(latestValue ?? 0) >= 1000;
const valueText = Number.isFinite(latestValue)
  ? new Intl.NumberFormat('en-GB', compact
      ? { notation: 'compact', maximumFractionDigits: 1 }
      : { maximumFractionDigits: 1 }
    ).format(latestValue)
  : '—';
const valueSize = width < 210 ? 23 : width < 420 ? 32 : 38;
const graphLeft = width < 210 ? '44%' : '40%';
const timeLabel = (value, index) => {
  if (width < 300 && index % 2 === 1) return '';
  const date = new Date(value);
  const hours = String(date.getUTCHours()).padStart(2, '0');
  if (width < 300) return `${hours}h`;
  const minutes = String(date.getUTCMinutes()).padStart(2, '0');
  return `${hours}:${minutes}`;
};

const finiteValues = points.map((point) => point[1]);
const initialValue = finiteValues.length ? finiteValues[0] : 0;
const observedMin = finiteValues.length ? Math.min(...finiteValues) : initialValue;
const observedMax = finiteValues.length ? Math.max(...finiteValues) : initialValue;
const minimumSpan = 10;
const baselineMin = Math.max(0, initialValue - minimumSpan / 2);
const baselineMax = Math.max(initialValue + minimumSpan / 2, baselineMin + minimumSpan);
let domainMin = baselineMin;
let domainMax = baselineMax;
if (observedMin < baselineMin) {
  const lowerExcursion = baselineMin - observedMin;
  const lowerHeadroom = Math.max(1, lowerExcursion * 0.15);
  domainMin = Math.max(0, observedMin - lowerHeadroom);
}
if (observedMax > baselineMax) {
  const upperExcursion = observedMax - baselineMax;
  const upperHeadroom = Math.max(1, upperExcursion * 0.15);
  domainMax = observedMax + upperHeadroom;
}
if (domainMax - domainMin < minimumSpan) domainMax = domainMin + minimumSpan;
const yDomain = { min: domainMin, max: domainMax };

return {
  animation: false,
  backgroundColor: 'transparent',
  graphic: [
    {
      type: 'text',
      left: width < 210 ? '3%' : '5%',
      top: '31%',
      silent: true,
      style: {
        text: valueText,
        fill: CYAN,
        fontFamily: 'Inter, Roboto, sans-serif',
        fontSize: valueSize,
        fontWeight: 500,
      },
    },
    ...(!points.length ? [{
      type: 'text',
      left: graphLeft,
      top: '35%',
      silent: true,
      style: {
        text: 'Awaiting samples',
        fill: MUTED,
        fontFamily: 'Inter, Roboto, sans-serif',
        fontSize: 11,
      },
