    boundaryGap: false,
    min: points.length ? points[0][0] : undefined,
    max: points.length ? points[points.length - 1][0] : undefined,
    splitNumber: width < 300 ? 2 : 3,
    minInterval: width < 300 ? 12 * 60 * 60 * 1000 : 6 * 60 * 60 * 1000,
    axisLine: { show: true, lineStyle: { color: 'rgba(148, 163, 184, 0.32)' } },
    axisTick: { show: false },
    axisLabel: {
      color: MUTED,
      fontSize: 9,
      hideOverlap: true,
      showMinLabel: true,
      showMaxLabel: true,
      margin: 7,
      formatter: timeLabel,
    },
    splitLine: { show: false },
  },
  yAxis: {
    type: 'value',
    show: false,
    min: yDomain.min,
    max: yDomain.max,
    splitLine: { show: true, lineStyle: { color: GRID } },
  },
  series: [{
    name: frame?.name || 'History',
    type: 'line',
    data: points,
    showSymbol: false,
